    # pylint: disable=too-many-instance-attributes, broad-except, unnecessary-pass
    def __init__(self, name, ue_id, configuration, rpc_client, reservation_validator=lambda: True):
        """

        :param name: name of UE
        :param ue_id: UE identifier e.g. serial number
        :param configuration: configuration of UE
        :param rpc_client:
        :param reservation_validator:
        """
        super().__init__(name, configuration)
        self.prepared = False
        self.ne_id = None
        self.reservation_verifying = False
        self.reservation_validator = reservation_validator
        config_reader = AndroidUeYamlConfigurationReader(configuration)
        self.config_reader = config_reader
        self.voice_call = None

        self.voice_call_dialing_timeout = config_reader.read_voice_call_dialing_timeout()

        self.qcat_exe_path = config_reader.read_qcat_exe_path()
        self.qcat_analyzer = config_reader.read_qcat_analyzer()
        self.diag_cfg_path = config_reader.read_diag_cfg_path()
        self.phone_number = config_reader.read_phone_number()
        self._network_mode_handler_type = config_reader.read_network_mode_switch_method()
        self.airplane_mode_switcher_text = config_reader.read_airplane_mode_switcher_text()
        self.airplane_mode_confirm_button_text = config_reader.read_airplane_mode_confirm_button_text()
        self.attach_service_call_number = self.config_reader.read_attach_service_call_number()
        self.detach_service_call_number = self.config_reader.read_detach_service_call_number()
        self.path_to_network_mode_type = config_reader.read_path_to_network_mode_type()
        self.ue_model = None
        self.ue_product = None
        self.ue_imei = None
        self.ue_os_version = None
        if ue_id is None:
            self.ue_id = "no S/N"
        else:
            self.ue_id = ue_id
            self.rpc_client = rpc_client

        self._create_ue_identification()
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {'area': 'UE', 'ue_id': self.ue_id})

        # deprecated secret_code - to be removed
        _logger = logging.getLogger(__name__)
        if config_reader.read_secret_code():
            _logger.warning("While changing the network mode still works with the secret code method,"
                            "secret code parameter is deprecated as it's not needed anymore- please remove it from your"
                            " config before the end of Q3, after that, you might encounter errors.")

        if config_reader.read_network_mode_switch_method() \
                and str(config_reader.read_network_mode_switch_method()).lower() not in AVAILABLE_NETWORK_MODE_METHODS:
            _logger.warning("You are using not supported `network_mode_switch_method` in config.")

    def _create_ue_identification(self):
        self.ne_id = UeIdentification(identifiers=[('android', self.ue_id)],
                                      network_elem_type='UE',
                                      specific_for_tool='android')

    @property
    def id(self):
        """
        Return ue id specific for used ue-implementation/tool.

        :return: tool specific ue id
        """
        return self.ue_id

    def connect_additional_pdn(self, pdn, ue_type="android"):
        """Attempts to insert new apn entry to UE"""
        pdn_from_config = self.config_reader.get_pdns(pdn)
        if pdn_from_config is None:
            raise KeyError(f'PDN "{pdn}" not found in configuration')
        pdn_config = self._convert_yaml_pdn_to_json_string(pdn_from_config)
        self.logger.debug(f"executing connect additional pdn (ue_type=\"{ue_type}\")")
        return self.rpc_client.connect_additional_pdn(ue_id=self.ue_id, pdn_name=pdn, pdn_config=pdn_config,
                                                      ue_type=ue_type)

    @staticmethod
    def _convert_yaml_pdn_to_json_string(pdn):
        import json
        return json.dumps(pdn)

    def disconnect_additional_pdn(self, pdn, ue_type="android"):
        """Attempts to remove apn entry, entry_name needs to be same as entryName defined in yaml/py config file"""
        try:
            pdn_from_config = self.config_reader.get_pdns(pdn)
            apn_name = pdn_from_config['entryName']
        except (KeyError, TypeError, AttributeError):
            raise Exception(f'PDN "{pdn}" not found in configuration')
        self.logger.debug("executing disconnect additional pdn")
        return self.rpc_client.disconnect_additional_pdn(ue_id=self.ue_id, apn_name=apn_name, ue_type=ue_type)

    def turn_mobile_data_on(self):
        """Turns mobile data on."""
        self.logger.debug("executing enable mobile data")
        return self.rpc_client.turn_mobile_data_on(ue_id=self.ue_id)

    def turn_mobile_data_off(self):
        """Turns mobile data off"""
        self.logger.debug("executing disable mobile data")
        return self.rpc_client.turn_mobile_data_off(ue_id=self.ue_id)

    def check_voicemail_notification(self, expected_result=-1):
        """
        Checks how many voicemail notifications there is on UE.
        If expected result is not provided, we assume that any amount of voicemail is an acceptable result.
        Only runnable on devices with Android 4.4 or higher.
        :param expected_result: Expected number of notifications
        :raises: :py:class:`UeProcedureError`: if expected result differs from actual
        :return:
        """
        os_ver = float(self.get_info('UE_OS_VER'))
        if os_ver < 4.4:
            raise UeProcedureError('Minimum version of Android for this keyword to work is 4.4!')

        expected_result = int(expected_result)
        result = self.rpc_client.act_on_voicemail(ue_id=self.ue_id, action='check_notification')

        if expected_result == int(result) or (expected_result == -1 and int(result) > 0):
            return True
        raise UeProcedureError(
            f'Expected voicemail notification count to contain {expected_result} message(s), actual number is {result}')

    def clear_voicemail_notification(self):
        """
        Clears notification about voicemail.
        Check voicemail notification will return 0 unless new voicemail appears.
        Also cleans on-screen voicemail notifications.
        :return:
        """
        return self.rpc_client.act_on_voicemail(ue_id=self.ue_id, action='clear_notification')

    def send_ussd_message(self, ussd_request):
        """
        Sends new USSD request form UE to network
        Only runnable on devices with Android 8.0 or higher.
        :param ussd_request:USSD request code which we want to sent to network
        :raises: :py:class:`UeProcedureError`: If UE this method is runs on Android lower than 8.0
        :return:
        """
        android_ver = float(self.get_info('OS_VERSION'))
        if android_ver < MIN_VERSION_TO_RUN_USSD_CODES:
            raise UeProcedureError(f'Send USSD is supported only on Android 8.0 and higher! Used {android_ver}')
        self.logger.info(f'Trying to send USSD request: {ussd_request}')
        return self.rpc_client.act_on_ussd_code(ue_id=self.ue_id, ussd_code=ussd_request, action='send')

    def get_ussd_response(self, ussd_request_response, expected_result):
        """
        Gets USSD code response from network and validates with expected result
        Only runnable on devices with Android 8.0 or higher.
        :param ussd_request_response:USSD code for which we want to retrieve response for validation
        :param expected_result:Response string we expect to get
        :raises: :py:class:`UeProcedureError`: If UE this method is runs on Android lower than 8.0
        :raises: :py:class:`UeProcedureError`: If expected result is different than actual result
        :return: True if result was same as expected result
        """
        android_ver = float(self.get_info('OS_VERSION'))
        if android_ver < MIN_VERSION_TO_RUN_USSD_CODES:
            raise UeProcedureError(f'Get USSD is supported only on Android 8.0 and higher! Used {android_ver}')
        self.logger.info('Trying to retrieve response for '
                         f'{"last" if ussd_request_response is None else ussd_request_response} USSD request')
        result = self.rpc_client.act_on_ussd_code(ue_id=self.ue_id, ussd_code=ussd_request_response,
                                                  action='get_result')
        self.logger.info(f'Response for {ussd_request_response} USSD request is {result}')

        expected_result_for_compare = self._prepare_string_for_compare(expected_result)
        actual_result_for_compare = self._prepare_string_for_compare(result)

        self.logger.info(f'expected result post string parsing:{expected_result_for_compare}\n'
                         f'actual result post string parsing:{actual_result_for_compare}\n'
                         f'expected result:{expected_result}\nactual result:{result}')
        if expected_result_for_compare == actual_result_for_compare:
            return True
        raise UeProcedureError(
            f'For ussd code {ussd_request_response} expected result was "{expected_result}" but actual is "{result}"')

    def start_audio_playback(self, audio_file_path,
                             alsa_mixer_command="alsa_amixer cset name='Incall_Music Audio Mixer MultiMedia1' '1'"):
        """
        Executes commands required to inject voice into voice call and starts playback of specified audio file on UE
        :param audio_file_path: absolute path to audio file on UE
        :param alsa_mixer_command: Cmd to run alsa amixer. Because some UEs might have different commands,
                                   user can specify command run to fit
        her/his needs
        :return:
        """
        self.logger.debug(f'voice injection started: alsa_mixer_command={alsa_mixer_command}')
        result = self.rpc_client.start_audio_playback(ue_id=self.ue_id, audio_file_path=audio_file_path)
        if 'Successfully started playing file' not in result:
            raise UeProcedureError(f'Error when trying to inject voice into voice call:{result}')

    def stop_audio_playback(self):
        """
        Stops previously started audio playback on UE
        This won't stop audio playback from apps other than UeManager!
        :return:
        """
        self.rpc_client.stop_audio_playback(ue_id=self.ue_id)

