    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        self.logger.debug("checking whether UE can be reserved on taf.ue.proxy")
        reserved_ues = self.rpc_client.get_reserved_ues().get("ue_ids", [])
        self.logger.debug(f"list of already reserved UEs on taf.ue.proxy: {reserved_ues}")
        if self.ue_id in reserved_ues:
            raise UeAlreadyReserved(
                f"UE with serial number \"{self.ue_id}\" cannot be reserved, because is already reserved. "
                f"The reservation could be made manually or by previous Robot TC.\n"
                f"Before re-execution:\n"
                f"1) make sure that UE PC isn't used by other tester or Robot TC AND\n"
                f"2) repair the environment:\n"
                f"  a) restart taf.ue.proxy service OR\n"
                f"  b) release UE manually: open \"{self.rpc_client.remote_url}/docs\" -> open \"release_ue\" endpoint "
                f"-> button \"Try it out\" -> provide ue_id \"{self.ue_id}\" in request body -> button \"Execute\"")
        self.logger.debug("prepare_ue before calling reserve_ue on taf.ue.proxy")
        self.phone_number = self.config_reader.read_phone_number()
        self.prepared = self.rpc_client.reserve_ue(ue_id=self.ue_id, ue_config={
            'qualcomm_prototype': self.config_reader.read_qualcomm_prototype(),
            'is_rooted': self.config_reader.read_is_rooted(),
            'imei': self.config_reader.read_imei(),
            'imsi': self.config_reader.read_imsi(),
            'phone_number': self.config_reader.read_phone_number(),
            'voice_call_technology': self.config_reader.read_voice_call_technology(),
            'voice_call_technology_timeout': self.config_reader.read_voice_call_technology_timeout(),
            'voice_call_dialing_timeout': self.config_reader.read_voice_call_dialing_timeout(),
            'network_mode_handler_type': self.config_reader.read_network_mode_switch_method(),
            'network_mode_handler_config': self._prepare_network_mode_handler_config(self.config_reader.read_network_mode_switch_method()),
            'access': self.config_reader.read_access(),
        })
        self.logger.debug("prepare_ue after calling reserve_ue on taf.ue.proxy")
        self.ue_model = self.get_info('device_model')  # ensure UE has connected and is working
        self.logger.debug("prepare_ue after get model")
        self._log_ue_pc_diagnostic_info()
        # # self._configure_logging_on_ue()  # TODO https://jiradc.ext.net.nokia.com/browse/TAUE-1411
        return self.prepared

