    def _log_ue_pc_diagnostic_info(self):
        raw_logger = logging.getLogger("ute_ue")
        diagnostic_data = requests.get(url=f"{self.rpc_client.remote_url}/about").json()

        warn_about_latest_uepc_libraries_version(raw_logger, {
            "taf.ue.proxy": diagnostic_data.get("version", "0.0.0"),
            "taf.ue.proxy.access.android": self._get_access_plugin_version(diagnostic_data, "android"),
        })
        warn_about_latest_naa_version(raw_logger, self._get_naa_version())
        robot_logger.info(f"UE {self.ue_id} proxy environment: " + str(json.dumps(diagnostic_data,
                                                                                  sort_keys=False,
                                                                                  indent=4)))

