    def start_rrc_logs(self, diag_cfg_path=None, qmdl_size=None):
        """
        Start diag_mdlog on Android UE - start collecting qmdl file with rrc messages from qualcomm chipset.
        :param diag_cfg_path: path to DIAG.cfg file on Windows UE PC
                              (required to run diag_mdlog application on Android UE)
        :param qmdl_size: maximum qmdl file size in MB, int to specify the qmdl size if needed
        :return: Start RRC Logs endpoint status
        :raise DiagCfgFileNotFoundError: "diag_cfg_path" parameter not set!
        :raise QcatExeNotFoundError: "qcat_path parameter" not set!
        """
        diag_cfg_path = diag_cfg_path if diag_cfg_path else self.diag_cfg_path
        if not diag_cfg_path:
            raise DiagCfgFileNotFoundError('"diag_cfg_path" parameter not set! Start RRC logs keyword will not work!')
        if not self.qcat_exe_path:
            raise QcatExeNotFoundError('"qcat_path" (python/yaml) or "qcat_exe_path" (yaml) configuration parameter '
                                       'not set! Start RRC logs keyword will not work!')
        return self.rpc_client.start_rrc_logs(ue_id=self.ue_id, diag_cfg_path=diag_cfg_path,
                                              qmdl_size=qmdl_size, qcat_path=self.qcat_exe_path)

    # flake8: noqa: C901
    def stop_rrc_logs(self, qcat_analyzer=None, transfer_log_files_from_uepc=True, timeout=None,
                      logs_download_directory=get_robot_variable("OUTPUT_DIR"), filter_file_path=None, mdm=None,
                      log_zip_name='rrc_logs', return_rrc_log=False, use_decoding=True):
        """
        Stop diag_mdlog application on Android UE, convert qmdl to .txt and return path to txt file on UE PC
        :param qcat_analyzer: '-analyzer' value used in QCAT command.
        :param transfer_log_files_from_uepc: if True, transfer log files from UE PC to UE PC
        :param timeout: timeout for transferring log files from UE PC to Robot VM
        :param logs_download_directory: path to directory on UE PC where log files will be downloaded
        :param log_zip_name: name of zip file with logs
        :param filter_file_path: path to filter file on UE PC
        :param mdm: mdm name
        :param return_rrc_log: (deprecated) if True warning will be printed
        :param use_decoding: if True, use decoding
        :return: Stop RRC Logs endpoint status
        """

        if return_rrc_log:
            location = "Robot VM PC" if transfer_log_files_from_uepc else "UE PC"
            self.logger.warning("`return_rrc_log` attribute is deprecated. "
                                f"All logs are located in files, on {location}.")
        if timeout is not None:
            self.logger.warning("'timeout' option is currently unavailable and does not work, you have to control time")
        use_decoding = self._standardize_use_decoding(use_decoding)
        transfer_log_files_from_uepc = self._standardize_transfer_log_files_from_uepc(transfer_log_files_from_uepc)
        qcat_analyzer = self._standardize_qcat_analyzer(qcat_analyzer)
        stop_result = self.rpc_client.stop_rrc_logs(ue_id=self.ue_id, qcat_analyzer=qcat_analyzer,
                                                    use_decoding=use_decoding,
                                                    filter_file_path=filter_file_path,
                                                    mdm=mdm)
        if transfer_log_files_from_uepc:
            self._download_rrc_logs(logs_download_directory, zip_name=log_zip_name)
        return stop_result

    def _standardize_use_decoding(self, use_decoding) -> bool:
        return False if str(use_decoding).lower() == 'false' else True

    def _standardize_transfer_log_files_from_uepc(self, transfer_log_files_from_uepc) -> bool:
        return False if str(transfer_log_files_from_uepc).lower() == 'false' else True

    def _standardize_qcat_analyzer(self, qcat_analyzer=None) -> str:
        return qcat_analyzer if qcat_analyzer else self.qcat_analyzer

    def _download_rrc_logs(self, logs_download_directory, zip_name):
        """
        Download rrc logs from ue pc to ue pc
        :param logs_download_directory: path to directory where log files will be downloaded
        :param zip_name: name of zip file
        :return: None
        """
        if not zip_name.lower().endswith(".zip"):
            zip_name = zip_name + ".zip"

        rrc_logs = self.rpc_client.download_rrc_logs_zip(ue_id=self.ue_id,
                                                         zip_name=zip_name,
                                                         request_type="get")
        Utils().save_zipped_files(zip_name, logs_download_directory, rrc_logs)
        self._rrc_logs_for_ta_messaging(os.path.join(logs_download_directory, zip_name))

    def _rrc_logs_for_ta_messaging(self, rrc_logs_path):
        """
        Provide rrc logs to ta_messaging library.

        :param rrc_logs_path: Path to rrc_logs on VM
        :return None:
        """
        qmdl_log_paths, dir_to_remove = self.__prepare_rrc_logs_for_ta_messaging(rrc_logs_path)
        self.logger.debug(f"qmdl_log_paths: {qmdl_log_paths}, dir_to_remove: {dir_to_remove}")
        if qmdl_log_paths:
            data = self._read_qmdl_log(qmdl_log_paths)
            self._provide_data_from_stop_rrc_to_ta_messaging(data)
            if dir_to_remove:
                Utils().remove_directory(dir_to_remove)
        else:
            self.logger.warning("Unable to prepare rrc logs for ta_messaging!")

    @staticmethod
    def __prepare_rrc_logs_for_ta_messaging(rrc_logs_path):
        """
        Prepare logs for ta_messaging.

        This function takes a path to rrc_logs (zip file / directory) and creates a new list of qmdl log paths
        that are relevant to the ta_messaging.

        :param rrc_logs_path: Path to rrc_logs on VM
        :return tuple(List[str], Optional[str]): qmdl_log_paths, dir_to_remove (in case rrc_logs are zipped)
        """
        if os.path.isdir(rrc_logs_path):
            file_list = Utils().list_files_from(rrc_logs_path)
            qmdl_log_paths = [os.path.join(rrc_logs_path, file) for file in file_list if file.endswith(".txt")]
            return qmdl_log_paths, None
        elif os.path.isfile(rrc_logs_path):
            Utils().unpack_zip_file(rrc_logs_path)
            rrc_logs_dir, rrc_log_ext = os.path.splitext(rrc_logs_path)
            file_list = Utils().list_files_from(rrc_logs_dir)
            qmdl_log_paths = [os.path.join(rrc_logs_dir, file) for file in file_list if file.endswith(".txt")]
            return qmdl_log_paths, rrc_logs_dir

    def _provide_data_from_stop_rrc_to_ta_messaging(self, data):
        """
        Provide data from stop rrc logs to ta_messaging.

        :param List data: A list of log entries, each entry is a string with data from rrc_logs.
        :return: None
        """
        try:
            from .message_sources.message_sources_file_based import AndroidFileMessageSource
            if AndroidFileMessageSource.ANDROID_QUEUE in aliases_registry():
                if not data:
                    self.logger.info("Couldn't get decoded qmdl file from VM")
                    return
                for log_file_contents in data:
                    aliases_registry()[AndroidFileMessageSource.ANDROID_QUEUE].put(log_file_contents)
        except ImportError:
            self.logger.info(
                "stop rrc - ta_messaging is not installed, can not provide data from stop rrc to ta_messaging")

    def _read_qmdl_log(self, logs_files_paths):
        """
        Read and parse a log files.

        This method takes the paths to a qmdl log files, reads its contents, and parses the log entries into a List.

        :param List[str] logs_files_paths: list of qmdl log paths that are relevant to the ta_messaging.
        :return List[str] data: A list of log entries, each entry is a string with data from rrc_logs.
        """
        idx = 0
        data = []
        self.logger.debug(f"_read_qmdl_log received these:{logs_files_paths} logpaths")
        while idx < len(logs_files_paths):
            self.logger.debug(f'logs_file_path[{idx}] = {logs_files_paths[idx]}')
            if logs_files_paths[idx].endswith('.txt'):
                with open(logs_files_paths[idx]) as f:
                    self.logger.debug(f"Returning decoded qmdl file {f.name}")
                    data.append(f.readlines())  # readlines returns a list of lines.
            idx += 1
        if not data:
            self.logger.debug("Didn't find any decoded qmdl files.")
        return data

    def change_network_mode(self, network_mode_args, network_mode_switch_method=None, path_to_network_mode_type=None,
                            network_mode_validation=True):
        """
        Changes network mode of UE. Not all UEs will support this method.

        See: https://confluence.ext.net.nokia.com/pages/viewpage.action?pageId=1759283943

        **Warning:**
        Getting and setting preferred network mode via "adb" is deprecated and may not work on newer Android versions
        (> Android 9). Try network_mode_handler_type=`keyevents` instead.

        **Info:**
            - "adb" uses adb_shell command for general settings in android to set right network-modes separated with
              "_". E.g. "NR_LTE_GSM_WCDMA" or "LTE_WCDMA". See below full list of network modes as available argument
              (popular at the beginning of the list):
              `NR_only`, `NR_LTE`, `LTE_only`, `GSM_only`, `WCDMA_only`, `Global`, `LTE_WCDMA`, `NR_LTE_WCDMA`,
              `NR_LTE_GSM_WCDMA`, `GSM_WCDMA_auto`, `CDMA_EvDo`, `CDMA_only`, `NR_LTE_GSM`, `EvDo_only`,
              `LTE_CDMA_EvDo`, `LTE_GSM_WCDMA`, `LTE_CDMA_EvDo_GSM_WCDMA`, `WCDMA_preferred`, `TD_SCDMA_only`,
              `TD_SCDMA_WCDMA`, `TD_SCDMA_LTE`, `TD_SCDMA_GSM`, `TD_SCDMA_GSM_LTE`, `TD_SCDMA_GSM_WCDMA`,
              `TD_SCDMA_WCDMA_LTE`, `TD_SCDMA_GSM_WCDMA_LTE`, `TD_SCDMA_GSM_WCDMA_CDMA_EvDo`,
              `TD_SCDMA_LTE_CDMA_EvDo_GSM_WCDMA`, `NR_LTE_CDMA_EVDO`, `NR_LTE_CDMA_EVDO_GSM_WCDMA`, `NR_LTE_TDSCDMA`,
              `NR_LTE_TDSCDMA_GSM`, `NR_LTE_TDSCDMA_WCDMA`, `NR_LTE_TDSCDMA_GSM_WCDMA`,
              `NR_LTE_TDSCDMA_CDMA_EVDO_GSM_WCDMA`.
              To see examples, please go to the link:
              https://confluence.ext.net.nokia.com/pages/viewpage.action?pageId=1759283943#Get/ChangePreferredNetworkMode-RobotExample.1
            - "keyevents" emulates physical tapping in the Android Settings application. Note, that system settings
              mostly has accumulated options for preferred network mode as "2G/3G/4G (auto)".

              **WARNING** Available options are possible to check in device's android settings and values depend on UE
              model and android version. E.g. on different UEs same option may be named differently, e.g.:
              "5G (recommended)" and "2G/3G/4G/5G (auto)".

              **NOTE** Xiaomi devices with Android 12+, `path_to_network_mode_type` should be used from Android
              root settings, because Xiaomi has its own settings tree and cannot jump to Network and Internet settings
              at a time, so other labels path is needed e.g. 'Mobile networks,5GAPNTelecom,Network'.
            - "secretcode" emulates physical tapping in the service menu. Note, that the service menu contains mostly
              specific technology (like "LTE_only" or "NR_only"). So this option is suggested for changing between
              specific ones. Here available options to set also strongly depends on UE model and android version.
              Possible values may be checked in the service menu of the UE:
              `Phone info` -> `Set preferred network type` list.

        See more in configuration examples:
            - https://confluence.ext.net.nokia.com/display/AbstractLibs/ute_ue%3A+YAML+configuration+file.
            - https://confluence.ext.net.nokia.com/display/AbstractLibs/taf.ue%3A+__init__.py+configuration+file

        :param network_mode_args: string, see UeManagerProtocol.network_mode_nums2names
        :param network_mode_switch_method: method to switch network mode;
                                           currently available: "adb", "keyevents", "secretcode";
                                           other values will produce an exception
        :param network_mode_validation: if True, check if network mode was changed successfully
                                        and raise an exception if not; turned on by default
        :param path_to_network_mode_type: string, path to network mode type choice setting;
                                          used if network_mode_switch_method="keyevents"
        :return: None
        """
        # if network_mode_switch_method is set - cache it for future use
        self._cache_network_mode_robot_kwargs(network_mode_handler_type=network_mode_switch_method,
                                              path_to_network_mode_type=path_to_network_mode_type)
        # if no network_mode_handler_type in cache - use default (now it's "adb")
        network_mode_switch_method = self._network_mode_handler_type or net_mode_utils.DEFAULT_NETWORK_MODE_HANDLER
        # check if user gives valid network mode
        network_mode = net_mode_utils.validate_network_mode_based_on_switch_method(
            network_mode_switch_method, network_mode_args)
        # prepare config for network mode switching
        network_mode_config = self._prepare_network_mode_handler_config(network_mode_switch_method)
        configuration = {
                            "switch_method": network_mode_switch_method,
                            "network_mode_handler_config": network_mode_config
                        }
        # make remote procedure call to change network mode
        return self.rpc_client.change_network_mode(ue_id=self.ue_id,
                                                   network_mode=network_mode,
                                                   configuration=configuration,
                                                   validation=network_mode_validation)

    def get_preferred_network_mode(self, network_mode_handler_type=None, path_to_network_mode_type=None):
        """
        Get network mode of UE. Not all UEs will support this method.

        See: https://confluence.ext.net.nokia.com/pages/viewpage.action?pageId=1759283943

        **Warning:**
        Getting and setting preferred network mode via "adb" is deprecated and may not work on newer Android versions
        (> Android 9). Try network_mode_handler_type=`keyevents` instead.

        **Info:**
            - "adb" uses adb_shell command to get information from general settings, but in most UEs this way
               is deprecated.
            - "keyevents" emulates physical tapping in the Android Settings application. Note, that system settings
              mostly has accumulated options for preferred network mode as "2G/3G/4G (auto)". So this method
              is suggested get common information in Android Settings.
            - "secretcode" emulates physical tapping in the service menu. Note, that the service menu contains mostly
              specific technology (like "LTE_only" or "NR_only"). So this option is suggested for getting much
              more specific information.
            - Please pay attention, that if Change Network Mode was used in specific "network_mode_handler_type",
              that than suggested way of getting feedback via Get Preferred Network Mode is in the same way.

        :param network_mode_handler_type: method to get network mode;
                                          currently available: "adb", "keyevents", "secretcode";
                                          other values will produce an exception
        :param path_to_network_mode_type: string, path to network mode type choice setting;
                                          Obligatory if network_mode_switch_method="keyevents" but can be skipped
                                          if configured within Ue object in config file
                                          Example value: "Mobile networks/Network mode"

        :return: Current preferred network mode
        """
        # if network_mode_handler_type is set - cache it for future use
        self._cache_network_mode_robot_kwargs(network_mode_handler_type=network_mode_handler_type,
                                              path_to_network_mode_type=path_to_network_mode_type)

        # if no network_mode_handler_type in cache - use default (now it's "adb")
        network_mode_handler_type = self._network_mode_handler_type or net_mode_utils.DEFAULT_NETWORK_MODE_HANDLER
        # prepare config for network mode switching
        network_mode_handler_config = self._prepare_network_mode_handler_config(network_mode_handler_type)

        # make remote procedure call to change network mode
        return self.rpc_client.get_preferred_network_mode(ue_id=self.ue_id,
                                                          network_mode_handler_type=network_mode_handler_type,
                                                          network_mode_handler_config=network_mode_handler_config)

    def _prepare_network_mode_handler_config(self, network_mode_handler_type):
        if network_mode_handler_type == "adb":
            return {'attach_service_call': self.attach_service_call_number,
                    'detach_service_call': self.detach_service_call_number,
                    'airplane_mode_switcher_text': self.airplane_mode_switcher_text,
                    'airplane_mode_confirm_button_text': self.airplane_mode_confirm_button_text}
        elif network_mode_handler_type == "keyevents":
            return {'path_to_network_mode_type': self.path_to_network_mode_type}
        elif network_mode_handler_type == "secretcode":
            return {}  # NAA opens radio info view by Android API, so secret code isn't needed
        else:
            return {}

    def _cache_network_mode_robot_kwargs(self, network_mode_handler_type, path_to_network_mode_type=None):
        """Some kind of cache for robot args in case of changing network mode"""
        if network_mode_handler_type:
            net_mode_utils.validate_network_mode_handler_type(network_mode_handler_type)
            self._network_mode_handler_type = network_mode_handler_type
            if path_to_network_mode_type:
                self.path_to_network_mode_type = path_to_network_mode_type

    def get_info(self, info_type, timeout=None):
        """
        Return information about UE
        Example:
            ue.get_info('mobile_app_version')
                --> '1.0.0'
            ue.get_info(['mobile_app_version', 'mobile_app_protocol_version'])
                --> {'mobile_app_version': '1.0.0', 'mobile_app_protocol_version': '10'}
            ue.get_info('all')
                --> {dict with all available ue information}
        Note: `info_type` is case-insensitive

        :param info_type: one (string) or more than one (list) of values:
            - 'NAME' - `device` UE info from `adb devices -l` command
            - 'SERIAL' - UE serial number
            - 'HARDWARE' - TODO: not implemented yet
            - 'IMSI' - IMSI number on UE
            - 'IMEI' - IMEI number on UE
            - 'BUILD_VERSION' - equivalent of `adb shell getprop ro.build.id`, but from android API
            - 'UE_FIRMWARE_VERSION' - copy of BUILD_VERSION (legacy option left for backward compatibility)
            - 'DEVICE_MODEL' - UE device model
            - 'COMMERCIAL_NAME' - `product` UE info from `adb devices -l` command
            - 'OS_VERSION' - Android version on UE presented as version integer (e.g. 26 for Android Oreo)
            - 'ANDROID_VER' - copy of OS_VERSION (legacy option left for backward compatibility)
            - 'UE_OS_VER' - copy of OS_VERSION (legacy option left for backward compatibility)
            - 'IPS' - returns a dict of apn_names, network_interface_names and its ip addresses both v4 and v6;
                    e.g. {"ap1.wroc/rmnet_data1": ["100.99.250.145"],
                          "wifi_interface/wlan0": ["192.168.1.47", "fe80::1c91:34ff:fef6:9ad1"]}
            - 'IP' - returns an ip address in active mobile network (legacy option, IPS is recommended to use instead)
            - 'SIGNAL_STRENGTH' - Current signal strength
            - 'SINR' - sinr
            - 'CELL_INFO' - JSON formatted cell info UE is attached to
            - 'VOLTE_ENABLED' - tells if volte is enabled
            - 'WIFI_ENABLED' - tells if wifi is enabled
            - 'MOBILE_DATA_ENABLED' - tells if mobile data is enabled
            - 'AIRPLANE_MODE_ENABLED' - tells if airplane mode is enabled
            - 'MCC' - mcc
            - 'MNC' - mnc
            - 'LAC' - lac
            - 'PCI' - pci
            - 'CELL_ID' - Cell UE is attached to
            - 'ENB_ID' - Interchangeable with cell id, added for cosmetic reasons. Returns cell UE is attached to
            - 'MOBILE_APP_VERSION' - NAA version, e.g. 1.4.0
            - 'MOBILE_APP_PROTOCOL_VERSION' - NAA version code, e.g. 10
            - 'PREFERRED_NET_MODE' - current preferred network mode
            - 'BATTERY_TEMPERATURE' - UEs battery temperature
            - 'TIMESTAMP' - UE device current date and time
            - 'NR_STATE' - 5G state
        :param timeout: int or string of float, time in seconds or None
        :return: string value for single info; dict {'info_name': 'info_value'} for multiple infos
        """
        if timeout is not None:
            self.logger.warning(f"`AndroidUe.get_info` method does not use `timeout` parameter,"
                                f" it will be omitted: timeout={timeout}")
        self.logger.debug(f"Defining get_ue_info query to proxy: info_type={info_type}")
        if isinstance(info_type, str):
            wanted_attrs = [info_type.lower()]
        elif isinstance(info_type, (list, tuple, set)):
            wanted_attrs = [info.lower() for info in info_type if isinstance(info, str)]
        else:
            raise TypeError(f"`AndroidUe.get_info` - wrong `info_type` parameter type: {type(info_type)}.\n"
                            f"Allowed types: str, list, set, tuple")
        if 'all' in wanted_attrs:
            wanted_attrs = []
        self.logger.debug(f"Sending get_ue_info query to proxy: wanted_attrs={wanted_attrs}")
        response = self.rpc_client.get_ue_info(ue_id=self.ue_id, ue_attributes=wanted_attrs)
        self.logger.debug(f"Getting get_ue_info response from proxy: {response}")

        # Get `ue_product`, `imei` and `os_version` from response and try to cache them if not set yet
        self.ue_product = response.get('commercial_name', self.ue_product or response.get('commercial_name'))
        self.ue_imei = response.get('imei', self.ue_imei or response.get('imei'))
        self.ue_os_version = response.get('os_version', self.ue_os_version or response.get('os_version'))

        return list(response.values())[0] if len(wanted_attrs) == 1 else response

    def attach(self, timeout=20, validation=True, top_cmd_only=False, **kwargs):
        """
        Perform attach on UE.

        :param timeout: timeout period
        :param validation: if True, check if attach state was changed successfully
                              and raise an exception if not; turned on by default
        :param top_cmd_only: if True:
                                - turns off airplane mode
                             if False:
                                - turns off airplane mode
                                - turns on mobile data
                                - turns on location
                                - checks if mobile data is connected (if validation==True) and logs an error if not
                                - verifies if the active voice call technology is the same as set in the config file
        :return: None
        """
        extra_params = {
            'attach_service_call': self.attach_service_call_number,
            'detach_service_call': self.detach_service_call_number,
            'airplane_mode_switcher_text': self.airplane_mode_switcher_text,
            'airplane_mode_confirm_button_text': self.airplane_mode_confirm_button_text,
            'validation': bool(strtobool(validation.lower()) if isinstance(validation, str) else validation),
            'top_cmd_only': bool(strtobool(top_cmd_only.lower()) if isinstance(top_cmd_only, str) else top_cmd_only)
        }
        self.rpc_client.attach_ue(ue_id=self.ue_id, timeout=timeout, extra_params=extra_params)

    def android_keep_reservation(self):
        """Perform keep reservation on UE PC."""
        # self._method_proxy(KEEP_RESERVATION_METHOD_NAME)
        raise NotImplementedError

    def detach(self, timeout=20, validation=True, top_cmd_only=False, **kwargs):
        """
        Perform detach on UE.

        :param timeout: timeout period
        :param validation: if True, check if detach state was changed successfully
                              and raise an exception if not; turned on by default
        :param top_cmd_only: if True limits to call only necessary (top level) detach command;
                              by default it is False
        :param kwargs: UE specific optional arguments:
                       - 'force_change_mode' - if True, UE will be forced to change flight-mode even with no active cell
        :return: None
        """
        extra_params = {
            'attach_service_call': self.attach_service_call_number,
            'detach_service_call': self.detach_service_call_number,
            'airplane_mode_switcher_text': self.airplane_mode_switcher_text,
            'airplane_mode_confirm_button_text': self.airplane_mode_confirm_button_text,
            'validation': bool(strtobool(validation.lower())) if isinstance(validation, str) else validation,
            'top_cmd_only': bool(strtobool(top_cmd_only.lower())) if isinstance(top_cmd_only, str) else top_cmd_only
        }
        # :optional param: force_change_mode: (str) - if True, force detach even if UE is not attached to network
        force_change_mode = kwargs.get('force_change_mode', False)
        if bool(strtobool(force_change_mode.lower()) if isinstance(force_change_mode, str) else force_change_mode):
            extra_params.update({'force_change_mode': True})
        self.rpc_client.detach_ue(ue_id=self.ue_id, timeout=timeout, extra_params=extra_params)

    def _create_data_transfer(self, name, dt_definition):
        """
        Abstract method for creating data transfer of specific type.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: data_transfer - object derivered from lte_data_transfer class
        """
        dt_class = self._get_data_transfer_class(dt_definition)
        data_transfer = dt_class(name, dt_definition, self._configuration, self, logger_name=self.ue_logger_name)
        self.logger.debug(f"Created new data transfer instance: {data_transfer}")
        scope.current_scope().uses(resource=data_transfer, resource_releaser=self._cleanup_data_transfer)
        return data_transfer

    @staticmethod
    def _get_data_transfer_class(dt_definition):
        """
        Returns a data transfer class based on protocol
        :return: dict
        """
        protocol_to_class = {'icmp': AndroidDataTransferIcmp,
                             'ftp': AndroidDataTransferFtp,
                             'http': AndroidDataTransferHttp}
        return protocol_to_class.get(dt_definition.protocol, AndroidDataTransfer)

    @staticmethod
    def _cleanup_data_transfer(data_transfer):
        # cleanup only DTs that are still active, skip not started or finished
        if data_transfer.success_started and data_transfer.is_dt_running:
            data_transfer.release_data_transfer()

    def _assert_advanced_call_features_available(self, definition):
        if definition.allow_parallel_calls or definition.with_video:
            self._raise_if_ue_not_able_to_track_vc_uri()

    def _create_voice_call(self, name, definition):
        self._overwrite_voice_call_definition_if_need(definition)
        self._assert_advanced_call_features_available(definition)
        return self._create_voice_call_instance(name, definition)

    def _create_voice_call_instance(self, name, vc_definition):
        """
        Method for creating voice call.

        :param name: name to be assigned to voice call. You must use it later on to reference given calls.
        :param vc_definition: object of VoiceCall that encapsulates all needed parameters.
        :return: voice_call - object
        """
        self.logger.debug(f"Creating voice call instance with name {name} started")
        voice_call = AndroidVoiceCall(name=name, definition=vc_definition,
                                      ue_id=self.ue_id, rpc_client=self.rpc_client,
                                      logger_name=self.ue_logger_name)
        self.voice_call = voice_call
        return voice_call

    def _cleanup_voice_call(self, vc):
        try:
            if vc.voice_call_uri in vc._list_voice_calls_uris():
                vc._end_call_on_ue()
        except Exception as e:
            self.logger.error(f'Exception during voice call {vc} cleanup. {e}')

    def voice_call_to_ue(self, other_ue, name=''):
        """
        Calls voice call to other UE.
        :param name: Voice call alias
        :param other_ue: AndroidUe
        :return: outcomming_voice_call:AndroidOutgoingVoiceCall, incomming_voice_call:AndroidIncomingVoiceCall
        """
        other_ue.set_auto_call_answering(False)
        # dialing_timeout has to be none
        outcomming_voice_call = self.start_voice_call(name=name,
                                                      definition=VoiceCallDefinition(to=other_ue.phone_number,
                                                                                     dialing_timeout=None))
        incomming_voice_call = other_ue.start_voice_call(name=name, definition=VoiceCallDefinition(to=None))
        incomming_voice_call.answer()
        return outcomming_voice_call, incomming_voice_call

    def _has_incoming_call(self):
        """
        Check if participant ue is in ringing state

        :return boolean: True if ue is in ringing state or False
        """
        ue_pool = aliases_registry()
        voice_calls = [ue_pool[ue] for ue in ue_pool.keys() if "VoiceCall" in ue_pool[ue].__class__.__name__]
        for voice_call in voice_calls:
            if voice_call.definition.to == self.phone_number:
                vc_state = self.rpc_client.get_voice_call_state(ue_id=self.ue_id, voice_call_id=voice_call.name)
                return vc_state == "ringing"
        self.logger.warning(f"Voice call with phone number: {self.phone_number} is not registered in"
                            f"aliases registry. Registered voice calls: {voice_calls}!")
        return False

    def _has_incoming_call_legacy(self):
        # TODO: check if this method is still needed
        # return self._method_proxy('get_calling_state').startswith('INC')
        return False

    def _voice_call_to_autoresponder_number(self, phone_number, name=''):
        """
        Calls voice call to given autoresponder number.
        :param phone_number:str
        :return: outcomming_voice_call:AndroidOutgoingVoiceCall
        """
        if not isinstance(phone_number, str):
            raise Exception('Please use string as a phone number.')
        dialing_timeout = 30
        outcomming_voice_call = self.start_voice_call(
            name=name, definition=VoiceCallDefinition(to=phone_number, dialing_timeout=dialing_timeout))
        return outcomming_voice_call

    def _overwrite_voice_call_definition_if_need(self, definition):
        if definition.dialing_timeout < 0 < self.get_voice_call_dialing_timeout():
            definition.dialing_timeout = self.get_voice_call_dialing_timeout()

    def is_able_voice_call_answer_and_conference(self):
        """
        Returns true if on this UE it is not able to answer voice call via start_voice_call or conference.
        :return: bool
        """
        android_api = self.get_info('ANDROID_VER')
        nums = android_api.split('.')
        return int(nums[0]) >= 6

    def _raise_if_ue_not_able_to_track_vc_uri(self):
        if not self.is_able_voice_call_answer_and_conference():
            raise Exception("Android version too low to support answering voice calls or voice calls conferences")

    def ensure_able_voice_call_answer_and_conference(self):
        """Raises exception if on this UE it is not able to answer voice call via start_voice_call or conference."""
        self._raise_if_ue_not_able_to_track_vc_uri()

    def get_voice_call_dialing_timeout(self):
        """
        Voice_call_dialing_timeout is a time between: start calling from UE TO answer call from receiver
        If voice call has not voice_call_dialing_timeout defined,
        then Voice Call would have UE's voice_call_dialing_timeout
        :return: voice_call_dialing_timeout
        """
        return self.voice_call_dialing_timeout

    def send_sms(self, destination, text):
        """
        Send SMS to given number with given text.

        :param destination: destination UE number
        :param text: Message that will be send to UE
        :return: None
        :raises UeManagerMobileVersionIncorrect if version of mobile app is too low
        """
        self.rpc_client.send_sms(ue_id=self.ue_id, phone_number=destination, text=text)

    def receive_sms(self, expected_number, expected_text, timeout):
        """
        Check SMS captured by mobile app.

        :param expected_number: Source UE phone number
        :param expected_text: Message that will be received from UE
        :param timeout: Waiting time for message
        :return: None
        """
        timeout = timestr_to_secs(timeout)
        current_time = time.time()
        return_message = f"Timeout reached. Not received sms from {expected_number}."
        while time.time() - current_time < timeout:
            response_sms = self.rpc_client.receive_sms(ue_id=self.ue_id)
            if response_sms['status']:
                is_sms_correct, return_message = self._verify_received_sms(number=response_sms['number'],
                                                                           expected_number=expected_number,
                                                                           text=response_sms['text'],
                                                                           expected_text=expected_text)
                if is_sms_correct:
                    return
            time.sleep(0.1)
        raise Exception(return_message)

    @staticmethod
    def _verify_received_sms(number, expected_number, text, expected_text):
        expected_number = expected_number.strip('+')
        number = number.strip('+')
        if number == expected_number:
            if text == expected_text:
                return True, "SMS and text match!"
            return False, f"Expected sms text: {expected_text}, got text: {text}"
        return False, f"Expected sms from: '{expected_number}', got from: '{number}'"

    def shutdown(self):
        """Shutdown is triggered at the end of current scope (it depends where Require UE was called)"""
        self.logger.debug('Shutting down the UE.')
        self.rpc_client.release_ue(ue_id=self.ue_id)
        self.logger.debug('Ue was shut down. Should be ready to use again now')

    def turn_wifi_on(self):
        """
        Turns wifi on

        :return: None
        """
        self.logger.debug("executing enable Wifi")
        return self.rpc_client.turn_wifi_on(ue_id=self.ue_id)

    def turn_wifi_off(self):
        """
        Turns wifi off

        :return: None
        """
        self.logger.debug("executing disable Wifi")
        return self.rpc_client.turn_wifi_off(ue_id=self.ue_id)

    def start_recording_voice(self, with_video=False):
        """
        Start recording voice (voice calls)
        :param with_video: bool: Determines if voice call with video will be recorded
        :return: None
        """
        self.logger.debug('Voice call recording switching starting..')
        self.rpc_client.start_recording_voice(ue_id=self.ue_id, with_video=with_video)
        self.logger.debug('Voice call recording switching start.. DONE')

    def stop_recording_voice(self, dump_to: str):
        """
        Stop recording voice (voice calls)
        :param dump_to: str: Local path to pull file with recording
        :return: None
        """
        self.logger.debug('Voice call recording switching stopping..')
        self.rpc_client.stop_recording_voice(ue_id=self.ue_id, local_file_dir=dump_to)
        self.logger.debug('Voice call recording switching stop.. DONE')

    def turn_volte_on(self):
        """Enable ability to make voLTE calls."""
        self.rpc_client.turn_volte_on(ue_id=self.ue_id)

    def turn_volte_off(self):
        """Disable ability to make voLTE calls."""
        self.rpc_client.turn_volte_off(ue_id=self.ue_id)

    def _prepare_string_for_compare(self, string):
        new_string = string.lower()
        self.logger.info(f'Changed string {string} to lowercase: {new_string}')
        self.logger.info(f'Encoded to utf-8: {new_string}')
        new_string = new_string.strip()
        self.logger.info(f'Stripped of whitespaces: {new_string}')
        return new_string

