    def validate_ue_info(self, info, expected_value, **kwargs):
        """
        Validates specified UE information
        Example:
            ue.validate_ue_info('mobile_app_version', '1.0.0')
            ue.validate_ue_info(['mobile_app_version', 'mobile_app_protocol_version'], ['1.0.0', '10'])
        Note: `info` is case-insensitive

        Available values are:

            - 'NAME' - `device` UE info from `adb devices -l` command
            - 'SERIAL' - UE serial number
            - 'HARDWARE' - TODO: not implemented yet
            - 'IMSI' - IMSI number on UE
            - 'IMEI' - IMEI number on UE
            - 'BUILD_VERSION' - equivalent of `adb shell getprop ro.build.id`, but from android API
            - 'UE_FIRMWARE_VERSION' - copy of BUILD_VERSION (legacy option left for backward compatibility)
            - 'DEVICE_MODEL' - UE device model
            - 'COMMERCIAL_NAME' - `product` UE info from `adb devices -l` command
            - 'OS_VERSION' - Android version on UE presented as version integer (e.g. 26 for Android Oreo)
            - 'ANDROID_VER' - copy of OS_VERSION (legacy option left for backward compatibility)
            - 'UE_OS_VER' - copy of OS_VERSION (legacy option left for backward compatibility)
            - 'IPS' - returns a dict of apn_names, network_interface_names and its ip addresses both v4 and v6;
                    e.g. {"ap1.wroc/rmnet_data1": ["100.99.250.145"],
                          "wifi_interface/wlan0": ["192.168.1.47", "fe80::1c91:34ff:fef6:9ad1"]}
            - 'IP' - returns an ip address in active mobile network (legacy option, IPS is recommended to use instead)
            - 'SIGNAL_STRENGTH' - Current signal strength
            - 'SINR' - sinr
            - 'CELL_INFO' - JSON formatted cell info UE is attached to
            - 'VOLTE_ENABLED' - tells if volte is enabled
            - 'WIFI_ENABLED' - tells if wifi is enabled
            - 'MOBILE_DATA_ENABLED' - tells if mobile data is enabled
            - 'AIRPLANE_MODE_ENABLED' - tells if airplane mode is enabled
            - 'MCC' - mcc
            - 'MNC' - mnc
            - 'LAC' - lac
            - 'PCI' - pci
            - 'CELL_ID' - Cell UE is attached to
            - 'ENB_ID' - Interchangeable with cell id, added for cosmetic reasons. Returns cell UE is attached to
            - 'MOBILE_APP_VERSION' - NAA version, e.g. 1.4.0
            - 'MOBILE_APP_PROTOCOL_VERSION' - NAA version code, e.g. 10
            - 'PREFERRED_NET_MODE' - current preferred network mode
            - 'BATTERY_TEMPERATURE' - UEs battery temperature
            - 'TIMESTAMP' - UE device current date and time
            - 'NR_STATE' - 5G state

        :param info: Info(s) we want to check, e.g. IP, Cell ID etc.
        :param expected_value: Value(s) that the specified info(s) should have.
        :raises: ValueDiffersFromExpected if actual value is different from expected
        :return: None
        """
        actual_value = self.get_info(info)
        # For serving multiple infos check
        if isinstance(info, (list, tuple, set)) and type(info) is type(expected_value):
            if set(actual_value.values()) == set(expected_value):
                return
        else:
            if str(expected_value) == str(actual_value):
                return
        raise ValueDiffersFromExpected(f"Expected {info} value = {expected_value}, actual {info} value = {actual_value}")

