    def set_mtk_sbp_feature(self, cmd_mode, feature_name, feature_value=None):
        """
        Set SBP feature on MTK UE using AT command - AT+ESBP. Available only for MTK UEs!

        Example:
        To run the following AT command: 'AT+ESBP=5,"SBP_NR_PARTIAL_BAND_UNDER_MCC",1', you need to provide values to
        the parameters as follows: parameter=5, feature_name="SBP_NR_PARTIAL_BAND_UNDER_MCC", feature_value="1"

        There were tested only following features:
        - SBP_NR_PARTIAL_BAND_UNDER_MCC
        - SBP_NR_SUPPORT_EXTENDED_BAND_77_USA

        :param cmd_mode: Mode of AT+ESBP command
        :param feature_name: Feature name
        :param feature_value: Parameters of configured feature
        """
        self.rpc_client.set_mtk_sbp_feature(ue_id=self.ue_id,
                                            cmd_mode=cmd_mode,
                                            feature_name=feature_name,
                                            feature_value=feature_value)

    def set_mtk_gmc_feature(self, oh_op=0, cc_dl=None, cc_ul=None,
                    bw_fr1_dl=None, bw_fr1_ul=None, bw_fr2_dl=None, bw_fr2_ul=None,
                    mimo_fr1_dl=None, mimo_fr2_dl=None, mimo_fr1_ul=None, mimo_fr2_ul=None):
        """
        Set GMC feature on MTK UE using AT command - AT+EGMC. Available only for MTK UEs!
        From Mediatek documentation excerpt:
            UEAssistanceInformation message is to contain:
            AT+EGMC=1,"NR_OVERHEATING",X,X,X,X,X,X,X,X,X,X,X,

        Example:
        To run the following AT command: 'AT+EGMC=1,"NR_OVERHEATING",1,2,1,,,,,1,1,,,', you need to provide values to
        the parameters as follows: (1, 2, 1, None, None, None, None, 1, 1, None, None)

        :param oh_op:       [0; 1] | EGMC.OverheatingOp | None
        :param cc_dl:       [0;31] | None
        :param cc_ul:       [0;31] | None
        :param bw_fr1_dl:   [0;11] | EGMC.ReducedAggregatedBandwitdh  | None
        :param bw_fr1_ul:   [0;11] | EGMC.ReducedAggregatedBandwitdh  | None
        :param bw_fr2_dl:   [0;11] | EGMC.ReducedAggregatedBandwitdh  | None
        :param bw_fr2_ul:   [0;11] | EGMC.ReducedAggregatedBandwitdh  | None
        :param mimo_fr1_dl: [0; 2] | EGMC.MimoDL  | None
        :param mimo_fr2_dl: [0; 2] | EGMC.MimoDL  | None
        :param mimo_fr1_ul: [0; 2] | EGMC.MimoUL  | None
        :param mimo_fr2_ul: [0; 2] | EGMC.MimoUL  | None
        :return: None
        """
        self.rpc_client.set_mtk_gmc_feature(ue_id=self.ue_id, oh_op=oh_op, cc_dl=cc_dl, cc_ul=cc_ul,
                    bw_fr1_dl=bw_fr1_dl, bw_fr1_ul=bw_fr1_ul, bw_fr2_dl=bw_fr2_dl, bw_fr2_ul=bw_fr2_ul,
                    mimo_fr1_dl=mimo_fr1_dl, mimo_fr2_dl=mimo_fr2_dl, mimo_fr1_ul=mimo_fr1_ul, mimo_fr2_ul=mimo_fr2_ul)

